"""Helper: launch a command in tmux at given size, send keys, capture pane text (no colors)."""
import subprocess, sys, time, os

def sh(cmd, **kw):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True, **kw).stdout

def start(name, cmd, cols=120, rows=30):
    subprocess.run(["tmux","kill-session","-t",name],capture_output=True)
    subprocess.run(["tmux","new-session","-d","-x",str(cols),"-y",str(rows),"-s",name,cmd])
    time.sleep(0.6)

