import subprocess, re, time
def cap_top_pos():
    ansi = subprocess.run(["tmux","capture-pane","-t","q","-p","-e"],capture_output=True,text=True).stdout.split("\n")
    seq=[]
    for l in ansi:
        idx=l.find("\u2590")
        if idx<0: continue
        m=re.findall(r"\x1b\[([0-9;]*)m", l[:idx])
        seq.append(m[-1] if m else "?")
