for i in range(60):
    subprocess.run(["tmux","send-keys","-t","q","Up"]); time.sleep(0.06)
for k in range(0,30):
    if k>0:
        subprocess.run(["tmux","send-keys","-t","q","Down"]); time.sleep(0.06)
    pos, name = cap_top_pos()
    print("k=%d pos=%s first=%s" % (k, pos, name))
EOF"}

