{"command": "cat > /tmp/pty.py <<'PYEOF'
#!/usr/bin/env python3
"""Run a command in a pty of a given size; send input; dump output (optionally styled)."""
import os, sys, pty, fcntl, termios, struct, select, time, signal, errno

def run(cmd, keys=(), cols=120, rows=30, wait=1.0, styled=False, after=None):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    out = b""
    def drain(t):
        nonlocal out
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.05)
            if r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    return False
                if not d: return False
                out += d
        return True
    drain(wait)
    for k in keys:
        try: os.write(fd, k.encode() if isinstance(k,str) else k)
        except OSError: break
        drain(after if after else 0.4)
    drain(wait)
    try:
        os.kill(pid, signal.SIGKILL)
    except OSError: pass
    try: os.close(fd)
    except OSError: pass
    try: os.waitpid(pid, 0)
    except OSError: pass
    if styled:
        return out
    import re
    s = out.decode("utf8","replace")
    s = re.sub(r"\x1b\[[0-9;:?]*[A-Za-z]", "", s)
    s = re.sub(r"\x1b\][^\x07]*\x07", "", s)
    return s

if __name__ == "__main__":
    import json
    args = json.loads(sys.argv[1])
    keys = args.get("keys", [])
    print(run(args["cmd"], keys, args.get("cols",120), args.get("rows",30), args.get("wait",1.0), args.get("styled",False), args.get("after")))
PYEOF
cd /tmp && python3 /tmp/pty.py '{"cmd":["/workspace/executable","--version"],"cols":120,"rows":30,"wait":0.5}' | cat -A | head"}

