fn cmd() -> Command {
    let mut c = Command::new("broot")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("ROOT").num_args(0..=1).value_name("ROOT").help("Root Directory"));
    for a in arg_defs() {
        let name = a.long.trim_start_matches('-').replace(' ', "_").replace('<', "").replace('>', "").trim_end_matches('_').to_string();
        let mut arg = Arg::new(name).long(a.long.trim_start_matches('-'));
        if !a.short.is_empty() {
            arg = arg.short(a.short.trim_start_matches('-'));
        }
        if a.long.contains('<') {
            // takes a value
            let vn = a.long.split_whitespace().nth(1).unwrap().trim_matches(|c| c=='<'||c=='>').to_string();
            arg = arg.value_name(vn).num_args(1).action(ArgAction::Set);
            if a.long == "--color <color>" {
                arg = arg.value_parser(clap::builder::PossibleValuesParser::new(["auto","yes","no"]))
                    .default_value("auto");
            }
            if a.long == "--set-install-state <state>" {
                arg = arg.value_parser(clap::builder::PossibleValuesParser::new(["undefined","refused","installed"]));
            }
            if a.long == "--height <height>" {
                arg = arg.value_parser(clap::builder::value_parser!(usize));
            }
            if a.long == "--max-depth <MAX_DEPTH>" {
                arg = arg.value_parser(clap::builder::value_parser!(usize));
            }
        } else {
            arg = arg.action(ArgAction::SetTrue);
        }
        c = c.arg(arg);
    }
    c
}

pub fn parse() -> Result<Cli, String> {
    let matches = match cmd().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // clap prints the error itself
            let _ = e.print();
            return Err("__clap__".to_string());
        }
    };
    if matches.get_flag("help") {
        let mut c = Cli::default();
        c.help = true;
        return Ok(c);
    }
    let mut c = Cli::default();
    c.version = matches.get_flag("version");
    c.help = matches.get_flag("help");
    c.root = matches.get_one::<String>("ROOT").map(|s| PathBuf::from(s));
    c.cmd = matches.get_one::<String>("cmd").cloned();
    c.color = matches.get_one::<String>("color").cloned();
    c.dates = flag(&matches, "dates");
    c.only_folders = flag(&matches, "only_folders");
    c.show_root_fs = flag(&matches, "show_root_fs");
    c.show_git_info = flag(&matches, "show_git_info");
    c.git_status = flag(&matches, "git_status");
    c.height = matches.get_one::<usize>("height").copied();
    c.hidden = flag(&matches, "hidden");
    c.gitignored = flag(&matches, "git_ignored");
    c.max_depth = matches.get_one::<usize>("max_depth").copied();
    c.permissions = flag(&matches, "permissions");
    c.sizes = flag(&matches, "sizes");
    c.trim_root = flag(&matches, "trim_root");
    c.show_git_file_info = flag(&matches, "show_git_file_info");
    c.whale_spotting = flag(&matches, "whale_spotting");
    c.sort_by_count = flag(&matches, "sort_by_count");
    c.sort_by_date = flag(&matches, "sort_by_date");
    c.sort_by_size = flag(&matches, "sort_by_size");
    c.sort_by_type_dirs_first = flag(&matches, "sort_by_type_dirs_first");
    c.sort_by_type_dirs_last = flag(&matches, "sort_by_type_dirs_last");
    c.no_tree = flag(&matches, "no_tree");
    c.tree = flag(&matches, "tree");
    c.no_sort = flag(&matches, "no_sort");
    c.outcmd = matches.get_one::<String>("outcmd").map(|s| PathBuf::from(s));
    c.verb_output = matches.get_one::<String>("verb_output").map(|s| PathBuf::from(s));
    c.install = flag(&matches, "install");
    c.set_install_state = matches.get_one::<String>("set_install_state").cloned();
    c.print_shell_function = matches.get_one::<String>("print_shell_function").cloned();
    c.listen = matches.get_one::<String>("listen").cloned();
    c.listen_auto = flag(&matches, "listen_auto");
    c.get_root = flag(&matches, "get_root");
    c.write_default_conf = matches.get_one::<String>("write_default_conf").map(|s| PathBuf::from(s));
    c.send = matches.get_one::<String>("send").cloned();
    c.config_dir = matches.get_one::<String>("conf").cloned();
    Ok(c)
}

fn flag(m: &clap::ArgMatches, name: &str) -> Option<bool> {
    m.get_flag(name).then_some(true)
}

/// Handle the args which cause immediate exit. Returns true if handled.
pub fn handle_special(c: &Cli) -> bool {
    if c.version {
        println!("broot {}", crate_version());
        return true;
    }
    if c.help {
        help::print_help(c);
        return true;
    }
    if let Some(shell) = &c.print_shell_function {
        match install::print_shell_function(shell) {
            Ok(s) => { print!("{}", s); }
            Err(e) => { eprintln!("{}", e); std::process::exit(1); }
        }
        return true;
    }
    if let Some(dir) = &c.write_default_conf {
        conf::write_default_conf(dir);
        return true;
    }
    if let Some(state) = &c.set_install_state {
        install::set_install_state(state);
        return true;
    }
    if c.install.unwrap_or(false) {
        install::install(true);
        return true;
    }
    false
}

pub fn crate_version() -> &'static str {
    "1.54.0"
}
