/// a style: fg, bg and flags
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct CompoundStyle {
    pub fg: Color,
    pub bg: Color,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
    pub crossed_out: bool,
}
impl Default for CompoundStyle {
    fn default() -> Self {
        CompoundStyle { fg: Color::None, bg: Color::None, bold: false, italic: false, underline: false, crossed_out: false }
    }
}
impl CompoundStyle {
    pub fn parse_pair(s: &str) -> (CompoundStyle, Option<CompoundStyle>) {
        // split on '/' (but not inside parentheses)
        let mut parts = Vec::new();
        let mut depth = 0;
        let mut cur = String::new();
        for ch in s.chars() {
            match ch {
                '(' => { depth += 1; cur.push(ch) }
                ')' => { depth -= 1; cur.push(ch) }
                '/' if depth == 0 => { parts.push(cur.clone()); cur.clear() }
                _ => cur.push(ch),
            }
        }
        parts.push(cur);
        let a = CompoundStyle::parse(&parts[0]);
        let b = if parts.len() > 1 { Some(CompoundStyle::parse(&parts[1])) } else { None };
        (a, b)
    }
    pub fn parse(s: &str) -> CompoundStyle {
        let mut st = CompoundStyle::default();
        let mut words: Vec<String> = Vec::new();
        let mut cur = String::new();
        for ch in s.chars() {
            match ch {
                '(' | ')' => { cur.push(ch) }
                ' ' | '\t' => { if !cur.is_empty() { words.push(cur.clone()); cur.clear() } }
                _ => cur.push(ch),
            }
        }
        if !cur.is_empty() { words.push(cur) }
        for w in words {
            match w.to_ascii_lowercase().as_str() {
                "bold" => st.bold = true,
                "italic" => st.italic = true,
                "underlined" | "underline" => st.underline = true,
                "crossedout" | "crossed-out" | "strikethrough" => st.crossed_out = true,
                _ => {
                    if let Some(c) = Color::parse(&w) {
                        if st.fg == Color::None { st.fg = c; } else { st.bg = c; }
                    }
                }
            }
        }
        st
    }
    /// escape sequence setting this style (fg then bg then attributes)
    pub fn fg_seq(&self) -> String { self.fg.fg_seq() }
    pub fn bg_seq(&self) -> String { self.bg.bg_seq() }
    pub fn full_prefix(&self) -> String {
        let mut s = String::new();
        if self.bold { s.push_str("\x1b[1m"); }
        if self.italic { s.push_str("\x1b[3m"); }
        if self.underline { s.push_str("\x1b[4m"); }
        if self.crossed_out { s.push_str("\x1b[9m"); }
        s
    }
}

