    pub fn new(fg: Color, bg: Color) -> Self { CompoundStyle { fg, bg, bold: false, italic: false, underline: false, crossed_out: false } }
    pub fn new2(fg: Color, bg: Color, attrs: &str) -> Self {
        let mut s = CompoundStyle::new(fg, bg);
        for w in attrs.split(|c: char| c == ' ' || c == ',' || c == '-') {
            match w.to_ascii_lowercase().as_str() {
                "bold" => s.bold = true,
                "italic" => s.italic = true,
                "underlined" | "underline" => s.underline = true,
                "crossedout" | "strikethrough" => s.crossed_out = true,
                _ => {}
            }
        }
        s
    }
    pub fn parse(s: &str) -> CompoundStyle {
        let mut st = CompoundStyle::default();
        let mut words: Vec<String> = Vec::new();
        let mut cur = String::new();
        for ch in s.chars() {
            match ch {
                '(' | ')' => cur.push(ch),
                ' ' | '\t' => { if !cur.is_empty() { words.push(cur.clone()); cur.clear() } }
                _ => cur.push(ch),
            }
        }
        if !cur.is_empty() { words.push(cur) }
        for w in words {
            match w.to_ascii_lowercase().as_str() {
                "bold" => st.bold = true,
                "italic" => st.italic = true,
                "underlined" | "underline" => st.underline = true,
                "crossedout" | "crossed-out" | "strikethrough" => st.crossed_out = true,
                _ => { if let Some(c) = Color::parse(&w) { if st.fg == Color::None { st.fg = c; } else { st.bg = c; } } }
            }
        }
        st
    }
    pub fn parse_pair(s: &str) -> (CompoundStyle, Option<CompoundStyle>) {
        let mut parts = Vec::new();
        let mut depth = 0;
        let mut cur = String::new();
        for ch in s.chars() {
            match ch {
                '(' => { depth += 1; cur.push(ch) }
                ')' => { depth -= 1; cur.push(ch) }
                '/' if depth == 0 => { parts.push(cur.clone()); cur.clear() }
                _ => cur.push(ch),
            }
        }
        parts.push(cur);
        let a = CompoundStyle::parse(&parts[0]);
        let b = if parts.len() > 1 { Some(CompoundStyle::parse(&parts[1])) } else { None };
        (a, b)
    }
    pub fn fg_seq(&self) -> String { self.fg.fg_seq() }
    pub fn bg_seq(&self) -> String { self.bg.bg_seq() }
}
impl Default for CompoundStyle {
    fn default() -> Self { CompoundStyle { fg: Color::None, bg: Color::None, bold: false, italic: false, underline: false, crossed_out: false } }
}

#[derive(Clone, Debug)]
pub struct Skin { pub k: std::collections::HashMap<String, CompoundStyle> }

impl Skin {
    pub fn get(&self, key: &str) -> &CompoundStyle {
        self.k.get(key).unwrap_or(&DEFAULT_KV[key])
    }
}

macro_rules! defskin {
    ($($name:ident : $fg:expr, $bg:expr $(, $at:expr)* );* $(;)?) => {
        pub static DEFAULT_KV: std::collections::HashMap<String, CompoundStyle> = {
            let mut m: std::collections::HashMap<String, CompoundStyle> = std::collections::HashMap::new();
            $( m.insert(stringify!($name).to_string(), CompoundStyle::new2($fg, $bg, $($at)*)); )*
            m
        };
        pub fn default_skin() -> Skin {
            let mut m: std::collections::HashMap<String, CompoundStyle> = std::collections::HashMap::new();
            $( m.insert(stringify!($name).to_string(), CompoundStyle::new2($fg, $bg, $($at)*)); )*
            Skin { k: m }
        }
    };
}

