    pub fn as_int(&self) -> Option<i64> {
        match self {
            Value::Int(i) => Some(*i),
            Value::Str(s) => s.trim().parse::<i64>().ok(),
            _ => None,
        }
    }
    pub fn as_arr(&self) -> Option<&Vec<Value>> { if let Value::Arr(a) = self { Some(a) } else { None } }
    pub fn as_obj(&self) -> Option<&Vec<(String, Value)>> { if let Value::Obj(o) = self { Some(o) } else { None } }
    pub fn is_null(&self) -> bool { matches!(self, Value::Null) }
    pub fn keys(&self) -> Vec<String> {
        if let Value::Obj(o) = self { o.iter().map(|(k, _)| k.clone()).collect() } else { vec![] }
    }
}

pub fn parse(src: &str) -> Result<Value, String> {
    let mut p = Parser { s: src.chars().collect(), i: 0 };
    let v = p.value(0)?;
    Ok(v)
}

struct Parser { s: Vec<char>, i: usize }
impl Parser {
    fn peek(&self) -> Option<char> { self.s.get(self.i).copied() }
    fn at(&self, k: usize) -> Option<char> { self.s.get(self.i + k).copied() }
    fn skip_ws(&mut self) {
        loop {
            while let Some(c) = self.peek() {
                if c == ' ' || c == '\t' || c == '\r' || c == '\n' { self.i += 1; } else { break; }
            }
            if let Some(c) = self.peek() {
                if c == '#' {
                    while let Some(c) = self.peek() { if c == '\n' { break; } self.i += 1; }
                    continue;
                }
                if c == '/' && self.at(1) == Some('/') {
                    while let Some(c) = self.peek() { if c == '\n' { break; } self.i += 1; }
                    continue;
                }
            }
            break;
        }
    }
    fn value(&mut self, _depth: usize) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            None => Ok(Value::Null),
            Some('{') => self.object(),
            Some('[') => self.array(),
            Some('"') => { let s = self.quoted('"')?; Ok(Value::Str(s)) }
            Some('\'') => { let s = self.quoted('\'')?; Ok(Value::Str(s)) }
            Some('`') => { let s = self.quoted('`')?; Ok(Value::Str(s)) }
            Some(_) => self.unquoted(),
        }
    }
    fn quoted(&mut self, q: char) -> Result<String, String> {
        // multi-line ''' strings
        if q == '\'' && self.at(1) == Some('\'') && self.at(2) == Some('\'') {
            self.i += 3;
            let mut out = String::new();
            loop {
                if self.peek().is_none() { break; }
                if self.peek() == Some('\'') && self.at(1) == Some('\'') && self.at(2) == Some('\'') { self.i += 3; break; }
                out.push(self.peek().unwrap()); self.i += 1;
            }
            return Ok(out.trim_matches('\n').to_string());
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None => break,
                Some(c) if c == q => { self.i += 1; break; }
                Some('\\') => {
                    self.i += 1;
                    match self.peek() {
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('0') => out.push('\0'),
                        Some(c2) => out.push(c2),
                        None => {}
                    }
                    self.i += 1;
                }
                Some(c) => { out.push(c); self.i += 1; }
            }
        }
        Ok(out)
    }
    fn unquoted(&mut self) -> Result<Value, String> {
        let start = self.i;
        // unquoted values end at , } ] : or newline, or a comment start
        while let Some(c) = self.peek() {
            match c {
                ',' | '}' | ']' | ':' | '\n' | '\r' => break,
                '#' => {
                    // '#' may appear inside a value only if preceded by whitespace
                    if self.i > start && (self.s[self.i - 1] == ' ' || self.s[self.i - 1] == '\t') { break; }
                    self.i += 1;
                }
                '/' if self.at(1) == Some('/') => break,
                _ => self.i += 1,
            }
        }
        let raw: String = self.s[start..self.i].iter().collect();
        let t = raw.trim();
        if t.is_empty() { return Ok(Value::Null); }
        if t == "true" { return Ok(Value::Bool(true)); }
        if t == "false" { return Ok(Value::Bool(false)); }
        if let Ok(i) = t.parse::<i64>() { return Ok(Value::Int(i)); }
        if let Ok(f) = t.parse::<f64>() { let _ = f; }
        Ok(Value::Str(t.to_string()))
    }
    fn object(&mut self) -> Result<Value, String> {
        self.i += 1; // {
        let mut pairs = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => break,
                Some('}') => { self.i += 1; break; }
                Some(',') => { self.i += 1; continue; }
                Some(_) => {
                    let key = self.key()?;
                    self.skip_ws();
                    if self.peek() == Some(':') { self.i += 1; }
                    let v = self.value(0)?;
                    pairs.push((key, v));
                }
            }
        }
        Ok(Value::Obj(pairs))
    }
    fn key(&mut self) -> Result<String, String> {
        self.skip_ws();
        match self.peek() {
            Some('"') | Some('\'') => { let q = self.peek().unwrap(); Ok(self.quoted(q)?) }
            Some(_) => {
                let start = self.i;
                while let Some(c) = self.peek() {
                    match c {
                        ':' | '\n' | '\r' | ',' | '}' => break,
                        '#' => { if self.i > start && (self.s[self.i - 1] == ' ' || self.s[self.i - 1] == '\t') { break; } self.i += 1; }
                        '/' if self.at(1) == Some('/') => break,
                        _ => self.i += 1,
                    }
                }
                let raw: String = self.s[start..self.i].iter().collect();
                Ok(raw.trim().to_string())
            }
        }
    }
    fn array(&mut self) -> Result<Value, String> {
        self.i += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => break,
                Some(']') => { self.i += 1; break; }
                Some(',') => { self.i += 1; continue; }
                Some(_) => {
                    let v = self.value(0)?;
                    items.push(v);
                }
            }
        }
        Ok(Value::Arr(items))
    }
}
