use crate::hjson::{self, Value};
use crate::skin::{self, CompoundStyle, Skin};
use std::path::{Path, PathBuf};

pub static DEFAULT_CONF_HJSON: &str = include_str!("../resources/default-conf/conf.hjson");
pub static DEFAULT_VERBS_HJSON: &str = include_str!("../resources/default-conf/verbs.hjson");

pub static DEFAULT_SKINS: &[(&str, &str)] = &[
    ("catppuccin-macchiato.hjson", include_str!("../resources/default-conf/skins/catppuccin-macchiato.hjson")),
    ("catppuccin-mocha.hjson", include_str!("../resources/default-conf/skins/catppuccin-mocha.hjson")),
    ("dark-blue.hjson", include_str!("../resources/default-conf/skins/dark-blue.hjson")),
    ("dark-gruvbox.hjson", include_str!("../resources/default-conf/skins/dark-gruvbox.hjson")),
    ("dark-orange.hjson", include_str!("../resources/default-conf/skins/dark-orange.hjson")),
    ("native-16.hjson", include_str!("../resources/default-conf/skins/native-16.hjson")),
    ("solarized-dark.hjson", include_str!("../resources/default-conf/skins/solarized-dark.hjson")),
