    ("white.hjson", include_str!("../resources/default-conf/skins/white.hjson")),
];

#[derive(Clone, Debug, PartialEq)]
pub enum Luma { Dark, Light, Unknown }

pub fn config_dir() -> PathBuf {
    if let Ok(d) = std::env::var("BROOT_CONFIG_DIR") {
        if !d.is_empty() { return PathBuf::from(d); }
    }
    if let Ok(d) = std::env::var("XDG_CONFIG_HOME") {
        if !d.is_empty() { return PathBuf::from(d).join("broot"); }
    }
    home_dir().join(".config").join("broot")
}
pub fn data_dir() -> PathBuf {
    if let Ok(d) = std::env::var("XDG_DATA_HOME") {
        if !d.is_empty() { return PathBuf::from(d).join("broot"); }
    }
    home_dir().join(".local").join("share").join("broot")
}
pub fn home_dir() -> PathBuf {
    std::env::var("HOME").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from("/"))
}

/// Write the default conf files in the given directory (no message printed)
pub fn write_default_files(dir: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dir)?;
    let cp = dir.join("conf.hjson");
    if !cp.exists() {
        std::fs::write(&cp, DEFAULT_CONF_HJSON)?;
    }
    let vp = dir.join("verbs.hjson");
    if !vp.exists() {
        std::fs::write(&vp, DEFAULT_VERBS_HJSON)?;
    }
    let sp = dir.join("skins");
    std::fs::create_dir_all(&sp)?;
    for (name, content) in DEFAULT_SKINS {
        let p = sp.join(name);
        if !p.exists() {
            std::fs::write(&p, content)?;
        }
    }
    Ok(())
}

pub fn write_default_conf(dir: &Path) {
    let _ = write_default_files(dir);
}

/// Print the message shown when conf files are created
pub fn print_new_conf_message(dir: &Path, sty: bool) {
    let d = dir.display().to_string();
    if sty {
        println!("New Configuration files written in \x1b[1m\"{}\"\x1b[0m.", d);
    } else {
        println!("New Configuration files written in \"{}\".", d);
    }
    println!("You should have a look at them: their comments will help you configure broot.");
    println!("You should especially set up your favourite editor in verbs.hjson.");
}

#[derive(Clone, Debug)]
pub struct VerbConf {
    pub name: String,             // invocation verb name (first word)
    pub invocation: String,       // full invocation (with args)
    pub shortcut: String,
    pub key: String,
    pub execution: String,
    pub internal: String,
    pub external: String,
    pub leave_broot: bool,
    pub auto_exec: bool,
    pub from_shell: bool,
    pub set_working_dir: bool,
    pub apply_to: String,
    pub extension: String,
    pub description: String,
    pub args_needed: bool,
    pub is_internal: bool,
}

#[derive(Clone, Debug)]
pub struct SpecialPath {
    pub path: String,
    pub show: String,
    pub list: String,
    pub sum: String,
}

#[derive(Clone, Debug)]
pub struct Conf {
    pub default_flags: String,
    pub date_time_format: String,
    pub show_selection_mark: bool,
    pub quit_on_last_cancel: bool,
    pub modal: bool,
    pub initial_mode: String,
    pub cols_order: Vec<String>,
    pub true_colors: Option<bool>,
    pub icon_theme: Option<String>,
    pub ext_colors: Vec<(String, String)>,
    pub content_search_max_file_size: u64,
    pub max_panels_count: usize,
    pub update_work_dir: bool,
    pub enable_kitty_keyboard: bool,
    pub lines_before_match_in_preview: usize,
    pub lines_after_match_in_preview: usize,
    pub terminal_title: Option<String>,
    pub reset_terminal_title_on_exit: bool,
    pub search_modes: Vec<(String, String)>,
    pub special_paths: Vec<SpecialPath>,
    pub verbs: Vec<VerbConf>,
    pub skin: Skin,
    pub syntax_theme: Option<String>,
}

impl Default for Conf {
    fn default() -> Self {
        Conf {
            default_flags: "".to_string(),
            date_time_format: "%Y/%m/%d %R".to_string(),
            show_selection_mark: true,
            quit_on_last_cancel: false,
            modal: false,
            initial_mode: "input".to_string(),
            cols_order: vec!["mark".into(), "git".into(), "size".into(), "date".into(), "permission".into(), "count".into(), "branch".into(), "name".into()],
            true_colors: None,
            icon_theme: None,
            ext_colors: vec![],
            content_search_max_file_size: 10_000_000,
            max_panels_count: 2,
            update_work_dir: true,
            enable_kitty_keyboard: false,
            lines_before_match_in_preview: 1,
            lines_after_match_in_preview: 1,
            terminal_title: None,
            reset_terminal_title_on_exit: false,
            search_modes: vec![],
            special_paths: vec![],
            verbs: vec![],
            skin: skin::default_skin(),
            syntax_theme: None,
        }
    }
}

/// Parse a single hjson conf value into the conf, applying it
fn apply(conf: &mut Conf, v: &Value) {
    if let Some(x) = v.get("default_flags") { if let Some(s) = x.as_str() { conf.default_flags = s.to_string(); } }
    if let Some(x) = v.get("date_time_format") { if let Some(s) = x.as_str() { conf.date_time_format = s.to_string(); } }
    if let Some(x) = v.get("show_selection_mark") { if let Some(b) = x.as_bool() { conf.show_selection_mark = b; } }
    if let Some(x) = v.get("quit_on_last_cancel") { if let Some(b) = x.as_bool() { conf.quit_on_last_cancel = b; } }
    if let Some(x) = v.get("modal") { if let Some(b) = x.as_bool() { conf.modal = b; } }
    if let Some(x) = v.get("initial_mode") { if let Some(s) = x.as_str() { conf.initial_mode = s.to_string(); } }
    if let Some(x) = v.get("true_colors") { if let Some(b) = x.as_bool() { conf.true_colors = Some(b); } }
    if let Some(x) = v.get("icon_theme") { if let Some(s) = x.as_str() { conf.icon_theme = Some(s.to_string()); } }
    if let Some(x) = v.get("max_panels_count") { if let Some(i) = x.as_int() { conf.max_panels_count = i.max(1) as usize; } }
    if let Some(x) = v.get("update_work_dir") { if let Some(b) = x.as_bool() { conf.update_work_dir = b; } }
    if let Some(x) = v.get("enable_kitty_keyboard") { if let Some(b) = x.as_bool() { conf.enable_kitty_keyboard = b; } }
    if let Some(x) = v.get("lines_before_match_in_preview") { if let Some(i) = x.as_int() { conf.lines_before_match_in_preview = i.max(0) as usize; } }
    if let Some(x) = v.get("lines_after_match_in_preview") { if let Some(i) = x.as_int() { conf.lines_after_match_in_preview = i.max(0) as usize; } }
    if let Some(x) = v.get("terminal_title") { if let Some(s) = x.as_str() { conf.terminal_title = Some(s.to_string()); } }
    if let Some(x) = v.get("reset_terminal_title_on_exit") { if let Some(b) = x.as_bool() { conf.reset_terminal_title_on_exit = b; } }
    if let Some(x) = v.get("syntax_theme") { if let Some(s) = x.as_str() { conf.syntax_theme = Some(s.to_string()); } }
    if let Some(x) = v.get("content_search_max_file_size") { if let Some(s) = x.as_str() { if let Some(n) = parse_size(s) { conf.content_search_max_file_size = n; } } else if let Some(i) = x.as_int() { conf.content_search_max_file_size = i.max(0) as u64; } }
    if let Some(x) = v.get("cols_order") { if let Some(a) = x.as_arr() { let c: Vec<String> = a.iter().filter_map(|y| y.as_str().map(|s| s.to_string())).collect(); if !c.is_empty() { conf.cols_order = c; } } }
    if let Some(x) = v.get("search_modes") { if let Some(o) = x.as_obj() { conf.search_modes = o.iter().map(|(k, val)| (k.clone(), val.as_str().unwrap_or("").to_string())).collect(); } }
    if let Some(x) = v.get("special_paths") { if let Some(o) = x.as_obj() {
        for (k, val) in o {
            let mut sp = crate::conf::SpecialPath { path: k.clone(), show: "auto".into(), list: "auto".into(), sum: "auto".into() };
            if let Some(s) = val.get("show").and_then(|y| y.as_str()) { sp.show = s.to_string(); }
            if let Some(s) = val.get("list").and_then(|y| y.as_str()) { sp.list = s.to_string(); }
            if let Some(s) = val.get("sum").and_then(|y| y.as_str()) { sp.sum = s.to_string(); }
            conf.special_paths.push(sp);
        }
    } }
    if let Some(x) = v.get("ext_colors") { if let Some(o) = x.as_obj() {
        for (k, val) in o { conf.ext_colors.push((k.clone(), val.as_str().unwrap_or("").to_string())); }
    } }
    if let Some(x) = v.get("verbs") { if let Some(a) = x.as_arr() {
        for item in a {
            if let Some(vv) = parse_verb(item) { conf.verbs.push(vv); }
        }
    } }
}

pub fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    let mut num = String::new();
    let mut unit = String::new();
    for c in s.chars() {
        if c.is_ascii_digit() || c == '.' { num.push(c); } else { unit.push(c); }
    }
    let v: f64 = num.parse().ok()?;
    let mult: f64 = match unit.trim().to_ascii_lowercase().as_str() {
        "" | "b" => 1.0,
        "k" | "kb" => 1000.0,
        "m" | "mb" => 1000.0 * 1000.0,
        "g" | "gb" => 1000.0 * 1000.0 * 1000.0,
        "t" | "tb" => 1e12,
        "p" | "pb" => 1e15,
        "ki" | "kib" => 1024.0,
        "mi" | "mib" => 1024.0 * 1024.0,
        "gi" | "gib" => 1024.0 * 1024.0 * 1024.0,
        "ti" | "tib" => 1099511627776.0,
        "pi" | "pib" => 1125899906842624.0,
        _ => 1.0,
    };
    Some((v * mult) as u64)
}

fn parse_verb(v: &Value) -> Option<VerbConf> {
    let invocation = v.get("invocation").and_then(|x| x.as_str()).or_else(|| v.get("name").and_then(|x| x.as_str()))?.to_string();
    let name = invocation.split_whitespace().next().unwrap_or("").to_string();
    let args = invocation.split_whitespace().skip(1).count();
    let internal = v.get("internal").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let external = v.get("external").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let execution = v.get("execution").and_then(|x| x.as_str()).unwrap_or("").to_string();
    Some(VerbConf {
        name,
        invocation,
        shortcut: v.get("shortcut").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        key: v.get("key").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        execution,
        internal: internal.clone(),
        external,
        leave_broot: v.get("leave_broot").and_then(|x| x.as_bool()).unwrap_or(false),
        auto_exec: v.get("auto_exec").and_then(|x| x.as_bool()).unwrap_or(true),
        from_shell: v.get("from_shell").and_then(|x| x.as_bool()).unwrap_or(false),
        set_working_dir: v.get("set_working_dir").and_then(|x| x.as_bool()).unwrap_or(false),
        apply_to: v.get("apply_to").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        extension: v.get("extension").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        description: v.get("description").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        args_needed: args > 0,
        is_internal: !internal.is_empty() || execution.starts_with(':') || external.is_empty() && execution.is_empty(),
    })
}

/// load the skin from a hjson value (either a "skin" object or a file import)
fn load_skin_from_value(conf: &mut Conf, v: &Value, base_dir: &Path) {
    if let Some(sk) = v.get("skin") {
        if let Some(o) = sk.as_obj() {
            for (k, val) in o {
                if let Some(s) = val.as_str() {
                    let (active, inactive) = CompoundStyle::parse_pair(s);
                    if let Some(inact) = inactive {
                        conf.skin.k.insert(format!("{}_inactive", k), inact);
                    }
                    conf.skin.k.insert(k.clone(), active);
                }
            }
        }
    }
    if let Some(st) = v.get("syntax_theme") { if let Some(s) = st.as_str() { conf.syntax_theme = Some(s.to_string()); } }
    let _ = base_dir;
}

/// Load all the conf files
pub fn load_conf(explicit: &Option<Vec<PathBuf>>, luma: Luma) -> Conf {
    let mut conf = Conf::default();
    let mut paths: Vec<PathBuf> = Vec::new();
    match explicit {
        Some(v) => {
            for p in v { paths.push(p.clone()); }
        }
        None => {
            let d = config_dir();
            paths.push(d.join("conf.hjson"));
            paths.push(d.join("verbs.hjson"));
        }
    }
    let mut skins_dir = config_dir().join("skins");
    for p in &paths {
        if !p.exists() { continue; }
        if let Ok(text) = std::fs::read_to_string(p) {
            if let Ok(v) = hjson::parse(&text) {
                apply(&mut conf, &v);
                if p.file_name().map(|f| f.to_string_lossy().starts_with("conf")).unwrap_or(false) {
                    // handle imports
                    if let Some(imps) = v.get("imports").and_then(|x| x.as_arr()) {
                        for imp in imps {
                            // luma condition
                            if let Some(l) = imp.get("luma").and_then(|x| x.as_arr()) {
                                let ls: Vec<String> = l.iter().filter_map(|y| y.as_str().map(|s| s.to_string())).collect();
                                let cur = match luma { Luma::Dark => "dark", Luma::Light => "light", Luma::Unknown => "unknown" };
                                if !ls.iter().any(|s| s == cur) { continue; }
                            }
                            if let Some(f) = imp.get("file").and_then(|x| x.as_str()) {
                                let fp = if f.starts_with('/') { PathBuf::from(f) } else { skins_dir.parent().unwrap_or(&config_dir()).join(f) };
                                let _ = &skins_dir;
                                if let Ok(t2) = std::fs::read_to_string(&fp) {
                                    if let Ok(v2) = hjson::parse(&t2) {
                                        load_skin_from_value(&mut conf, &v2, fp.parent().unwrap_or(Path::new("/")));
                                    }
                                }
                            }
                        }
                    }
                    load_skin_from_value(&mut conf, &v, p.parent().unwrap_or(Path::new("/")));
                }
            }
        }
    }
    conf
}
