    let cp = dir.join("conf.hjson");
    if !cp.exists() {
        std::fs::write(&cp, DEFAULT_CONF_HJSON)?;
    }
    let vp = dir.join("verbs.hjson");
    if !vp.exists() {
        std::fs::write(&vp, DEFAULT_VERBS_HJSON)?;
    }
    let sp = dir.join("skins");
    std::fs::create_dir_all(&sp)?;
    for (name, content) in DEFAULT_SKINS {
