    pub show_git_file_info: bool,
    pub max_depth: Option<usize>,
    pub sort: SortMode,
    pub no_tree: bool,
    pub respect_gitignore: bool,
}

impl Default for TreeOptions {
    fn default() -> Self {
        TreeOptions {
            show_hidden: false, show_gitignored: true, only_folders: false,
            git_status_filter: false, show_git_file_info: false, max_depth: None,
            sort: SortMode::None, no_tree: false, respect_gitignore: true,
        }
    }
}

