/// metadata of a path
pub struct Meta {
    pub is_dir: bool,
    pub is_symlink: bool,
    pub apparent: u64,
    pub blocks: u64,
    pub mtime: i64,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub dev_major: u64,
    pub dev_minor: u64,
    pub link_target: Option<String>,
}

pub fn stat_path(p: &Path) -> Option<Meta> {
    use std::os::unix::fs::MetadataExt;
    let md = match std::fs::metadata(p) {
        Ok(m) => m,
        Err(_) => return None,
    };
    let is_symlink = std::fs::symlink_metadata(p).map(|s| s.file_type().is_symlink()).unwrap_or(false);
    let blocks = md.blocks();
    let dev = md.dev();
    let mode = md.mode();
    Some(Meta {
        is_dir: md.is_dir(),
        is_symlink,
        apparent: md.len(),
        blocks: blocks * 512,
        mtime: md.mtime(),
        mode,
        uid: md.uid(),
        gid: md.gid(),
        dev_major: (dev >> 8) as u64,
        dev_minor: (dev & 0xff) as u64,
        link_target: if is_symlink { std::fs::read_link(p).ok().map(|l| l.to_string_lossy().to_string()) } else { None },
    })
}

pub fn size_on_disk(apparent: u64, blocks: u64) -> u64 { apparent.min(blocks) }

/// format a size the way broot does
pub fn format_size(v: u64) -> String {
    if v < 10_000 { return v.to_string(); }
    let units: [(&str, f64); 6] = [("", 1.0), ("K", 1000.0), ("M", 1_000_000.0), ("G", 1e9), ("T", 1e12), ("P", 1e15)];
    let mut i = 0;
    for k in (1..units.len()).rev() {
        if v as f64 / units[k].1 >= 10.0 { i = k; break; }
    }
    let mut x = v as f64 / units[i].1;
    if x.round() >= 1000.0 && i + 1 < units.len() {
        i += 1;
        x = v as f64 / units[i].1;
    }
    if x >= 10.0 { format!("{:.0}{}", x, units[i].0) } else { format!("{:.1}{}", x, units[i].0) }
}

