impl Users {
    pub fn new() -> Users {
        let mut u = Users { pass: std::collections::HashMap::new(), grp: std::collections::HashMap::new() };
        if let Ok(s) = std::fs::read_to_string("/etc/passwd") {
            for line in s.lines() {
                let f: Vec<&str> = line.split(':').collect();
                if f.len() > 2 { if let Ok(id) = f[2].parse::<u32>() { u.pass.insert(id, f[0].to_string()); } }
