/// sort the children of a node according to the sort mode
pub fn sort_children(node: &mut Node, opt: &TreeOptions) {
    if opt.sort == SortMode::None { return; }
    match opt.sort {
        SortMode::Count => node.children.sort_by(|a, b| {
            let ca = a.count.unwrap_or(1); let cb = b.count.unwrap_or(1);
            cb.cmp(&ca).then(a.name.cmp(&b.name))
        }),
        SortMode::Date => node.children.sort_by(|a, b| {
            let da = a.mtime.unwrap_or(0); let db = b.mtime.unwrap_or(0);
            db.cmp(&da).then(a.name.cmp(&b.name))
        }),
        SortMode::Size => node.children.sort_by(|a, b| {
            let sa = a.size.unwrap_or(0); let sb = b.size.unwrap_or(0);
            sb.cmp(&sa).then(a.name.cmp(&b.name))
        }),
        SortMode::TypeDirsFirst => node.children.sort_by(|a, b| {
            b.is_dir.cmp(&a.is_dir).then(a.name.cmp(&b.name))
        }),
        SortMode::TypeDirsLast => node.children.sort_by(|a, b| {
            a.is_dir.cmp(&b.is_dir).then(a.name.cmp(&b.name))
        }),
        _ => {}
    }
}

/// list of children names (sorted by name)
pub fn list_children(path: &Path) -> Vec<(String, bool)> {
    let mut v = Vec::new();
    if let Ok(rd) = std::fs::read_dir(path) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            let is_dir = e.file_type().map(|t| t.is_dir()).unwrap_or(false);
            v.push((name, is_dir));
        }
    }
    v.sort_by(|a, b| a.0.cmp(&b.0));
    v
}

/// deep compute of size/count/mtime of a directory
pub fn deep_info(path: &Path) -> (u64, u64, Option<i64>) {
    let (mut total, mut cnt, mut maxmt) = (0u64, 0u64, None);
    let mut stack = vec![path.to_path_buf()];
    let mut visited = 0;
    while let Some(p) = stack.pop() {
        visited += 1;
        if visited > 100_000 { break; }
        if let Some(m) = stat_path(&p) {
            if m.is_dir {
                if let Ok(rd) = std::fs::read_dir(&p) {
                    for e in rd.flatten() {
                        stack.push(e.path());
                    }
                }
                total += m.blocks;
            } else {
                total += size_on_disk(m.apparent, m.blocks);
                if m.blocks < m.apparent { /* sparse */ }
                maxmt = Some(maxmt.unwrap_or(0).max(m.mtime));
            }
            cnt += 1;
        }
    }
    (total, cnt, maxmt)
}

pub struct TreeBuilder<'a> {
    pub conf: &'a Conf,
    pub opt: TreeOptions,
    pub users: Users,
    pub budget: usize,
    pub force_one_level: bool,
}

impl<'a> TreeBuilder<'a> {
    /// build a node with its metadata and (possibly) its children
    pub fn build_node(&self, path: PathBuf, deep: bool) -> Node {
        let mut n = Node::new(path.clone());
        if let Some(m) = stat_path(&path) {
            n.is_dir = m.is_dir;
            n.is_symlink = m.is_symlink;
            n.link_target = m.link_target;
            n.mtime = Some(m.mtime);
            n.perm = Some(m.mode);
            n.uid = m.uid;
            n.gid = m.gid;
            n.dev_major = Some(m.dev_major);
            n.dev_minor = Some(m.dev_minor);
            n.apparent = m.apparent;
            n.real_size = m.blocks;
            n.size = Some(size_on_disk(m.apparent, m.blocks));
            n.sparse = m.blocks < m.apparent;
            n.extension = Node::extension_of(&n.name);
        } else {
            n.has_error = true;
        }
        if deep || n.is_dir {
            if n.is_dir {
                let (s, c, mt) = deep_info(&path);
                n.real_size = s;
                n.size = Some(s);
                n.count = Some(c);
                if let Some(m) = mt { n.mtime = Some(n.mtime.unwrap_or(0).max(m)); }
            }
        }
        n
    }

    /// grow the tree to fill the available height
    pub fn grow(&self, node: &mut Node, height: usize) {
        let _ = height;
    }
}
