pub fn deep_info(path: &Path, max: usize) -> (u64, u64, Option<i64>) {
    let (mut total, mut cnt, mut maxmt) = (0u64, 0u64, None);
    let mut stack = vec![path.to_path_buf()];
    let mut visited = 0;
    while let Some(p) = stack.pop() {
        visited += 1;
        if visited > max { break; }
        if let Some(m) = stat_path(&p) {
            if m.is_dir {
                if let Ok(rd) = std::fs::read_dir(&p) { for e in rd.flatten() { stack.push(e.path()); } }
                total += m.blocks;
            } else {
                total += size_on_disk(m.apparent, m.blocks);
                maxmt = Some(maxmt.unwrap_or(0).max(m.mtime));
            }
            cnt += 1;
        }
    }
    (total, cnt, maxmt)
}

pub struct Builder<'a> {
    pub opt: TreeOptions,
    pub users: Users,
    pub budget: usize,
    pub one_level: bool,
    pub conf: &'a Conf,
    pub gitignore: Vec<(PathBuf, Vec<String>)>,
}

impl<'a> Builder<'a> {
    pub fn node_meta(&self, path: &Path, name: &str, is_dir: bool) -> Node {
        let mut n = Node::new(path.to_path_buf());
        n.is_dir = is_dir;
        if let Some(m) = stat_path(path) {
            n.is_dir = m.is_dir; n.is_symlink = m.is_symlink; n.link_target = m.link_target;
            n.mtime = Some(m.mtime); n.perm = Some(m.mode); n.uid = m.uid; n.gid = m.gid;
            n.dev_major = Some(m.dev_major); n.dev_minor = Some(m.dev_minor);
            n.apparent = m.apparent; n.real_size = m.blocks;
            n.size = Some(size_on_disk(m.apparent, m.blocks));
            n.sparse = m.blocks < m.apparent && m.apparent > 0;
        } else { n.has_error = true; }
        n.extension = Node::extension_of(name);
        n
    }

    /// add the children of a node as *unexpanded* entries
    pub fn add_children(&self, node: &mut Node) {
        if !node.is_dir { return; }
        let entries = list_children(&node.path);
        let mut kids = Vec::new();
        for (name, is_dir) in entries {
            if name.starts_with('.') && !self.opt.show_hidden { continue; }
            let p = node.path.join(&name);
            let mut n = self.node_meta(&p, &name, is_dir);
            if !self.opt.show_hidden && name.starts_with('.') { continue; }
            if self.opt.only_folders && !n.is_dir { continue; }
            if !self.opt.show_gitignored && self.is_ignored(&p, &name, n.is_dir) { continue; }
            kids.push(n);
        }
        node.children = kids;
        node.expanded = true;
    }

    pub fn is_ignored(&self, path: &Path, name: &str, is_dir: bool) -> bool {
        // simple gitignore handling: read .gitignore files along the path
        let mut dir = path.parent().map(|p| p.to_path_buf());
        while let Some(d) = dir {
            let gi = d.join(".gitignore");
            if let Ok(text) = std::fs::read_to_string(&gi) {
                for line in text.lines() {
                    let l = line.trim();
                    if l.is_empty() || l.starts_with('#') { continue; }
                    let (neg, pat) = if let Some(p) = l.strip_prefix('!') { (true, p.trim().to_string()) } else { (false, l.to_string()) };
                    let base = pat.split('/').last().unwrap_or(&pat).to_string();
                    if base == name {
                        if !neg { return true; }
                    }
                }
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
        false
    }

    /// fill the subtree with metadata (deep size/count/date) for a node and its children
    pub fn fill_deep(&self, node: &mut Node, depth: usize) {
        if !node.is_dir { return; }
        let (s, c, mt) = deep_info(&node.path, 200_000);
        node.real_size = s; node.size = Some(s); node.count = Some(c);
        if let Some(m) = mt { node.mtime = Some(node.mtime.unwrap_or(0).max(m)); }
        if self.one_level { return; }
        if depth > 1 { return; }
    }

    /// grow: expand dirs (cyclic order) until the height is filled
    pub fn grow(&self, root: &mut Node, height: usize) {
        if self.one_level { return; }
        loop {
            let lines = root.line_count();
            if lines >= height { break; }
            // find the next unexpanded dir, in cyclic order
            if !self.expand_next(root, true) { break; }
        }
    }

    /// expand the next unexpanded dir in cyclic order; returns false when none left
    fn expand_next(&self, node: &mut Node, _first: bool) -> bool {
        // breadth-first with cyclic start
        if !node.expanded && node.is_dir {
            self.add_children(node);
            // deep info for the children
            for c in node.children.iter_mut() {
                if c.is_dir { let (s, ct, mt) = deep_info(&c.path, 200_000); c.real_size = s; c.size = Some(s); c.count = Some(ct);
                    if let Some(m) = mt { c.mtime = Some(c.mtime.unwrap_or(0).max(m)); } }
            }
            return true;
        }
        // cyclic order over children: start at index 1
        let len = node.children.len();
        if len == 0 { return false; }
        for k in 0..len {
            let idx = if len > 1 { 1 + k } else { 0 } % len;
            if node.children[idx].is_dir {
                if self.expand_next(&mut node.children[idx], false) { return true; }
            }
        }
        false
    }

    /// trim the tree so that it fits in `height` lines
    pub fn trim(&self, root: &mut Node, height: usize) {
        loop {
            let lines = root.line_count();
            if lines <= height { break; }
            if !self.trim_once(root) { break; }
        }
    }

    /// one trimming step: remove the last child of the first dir (tree order) having children
    fn trim_once(&self, node: &mut Node) -> bool {
        // find in tree order the first dir with children
        if !node.children.is_empty() {
            let mut idx = None;
            for (i, c) in node.children.iter().enumerate() {
                if !c.children.is_empty() || (c.expanded && c.unlisted > 0) { idx = Some(i); break; }
                if c.expanded && c.children.is_empty() && c.unlisted > 0 { idx = Some(i); break; }
            }
            if let Some(i) = idx {
                let removed = self.trim_once(&mut node.children[i]);
                if removed { return true; }
                // remove its last child
                let c = &mut node.children[i];
                if !c.children.is_empty() {
                    let had_unlisted = c.unlisted > 0;
                    c.children.pop();
                    c.unlisted += 1;
                    if !had_unlisted && c.unlisted == 1 {
                        // the marker line costs one line: also remove the first child
                        if c.children.len() > 1 { c.children.remove(0); c.unlisted += 1; }
                        else if c.children.len() == 1 { c.children.remove(0); c.unlisted += 1; }
                    }
                    return true;
                } else if c.expanded && c.unlisted > 0 {
                    // nothing to remove here; try the next sibling
                }
            }
        }
        // try the children of the siblings
        for c in node.children.iter_mut() {
            if self.trim_once(c) { return true; }
        }
        // nothing removable inside: drop the node's own children entirely
        if !node.children.is_empty() {
            let n = node.children.len();
            node.children.clear();
            node.unlisted += n;
            return true;
        }
        false
    }
}
