pub struct Cols {
    pub git: usize,
    pub size: usize,
    pub date: usize,
    pub perm: usize,
    pub count: usize,
    pub bar: bool,
    pub device_id: bool,
}

pub fn perm_string(mode: u32) -> String {
    let mut s = String::new();
    let rwx = |bit: u32, ch: char, sub: char| if mode & bit != 0 { ch } else { sub };
    s.push(rwx(0o400, 'r', '_'));
    s.push(rwx(0o200, 'w', '_'));
    s.push(rwx(0o100, 'x', '_'));
    s.push(rwx(0o040, 'r', '_'));
    s.push(rwx(0o020, 'w', '_'));
    s.push(rwx(0o010, 'x', '_'));
    s.push(rwx(0o004, 'r', '_'));
    s.push(rwx(0o002, 'w', '_'));
    s.push(rwx(0o001, 'x', '_'));
    s
}

pub struct RenderedLine {
    pub cells: Vec<(String, CompoundStyle)>,
}

