pub fn deep_info(path: &Path, max: usize) -> (u64, u64, Option<i64>) {
    let (mut total, mut cnt, mut maxmt) = (0u64, 0u64, None);
    let mut stack = vec![path.to_path_buf()];
    let mut visited = 0;
    while let Some(p) = stack.pop() {
        visited += 1;
        if visited > max { break; }
        if let Some(m) = stat_path(&p) {
            if m.is_dir {
                if let Ok(rd) = std::fs::read_dir(&p) { for e in rd.flatten() { stack.push(e.path()); } }
                total += m.blocks;
            } else {
                total += size_on_disk(m.apparent, m.blocks);
                maxmt = Some(maxmt.unwrap_or(0).max(m.mtime));
            }
            cnt += 1;
        }
    }
    (total, cnt, maxmt)
}

/// git information for a directory
pub struct GitInfo {
    pub branch: Option<String>,
    pub statuses: std::collections::HashMap<PathBuf, GitStatus>,
    pub insertions: usize,
    pub deletions: usize,
}

pub fn git_info(dir: &Path) -> Option<GitInfo> {
    let out = Command::new("git").arg("-C").arg(dir).arg("status")
        .arg("--porcelain=v1").arg("-z").arg("--untracked-files=all").output().ok()?;
    if !out.status.success() { return None; }
    let s = String::from_utf8_lossy(&out.stdout);
    let mut statuses = std::collections::HashMap::new();
    let mut ins = 0; let mut del = 0;
    for entry in s.split('\0') {
        if entry.is_empty() { continue; }
        let (code, path) = match entry.find(' ') {
            Some(i) => (&entry[..i], &entry[i + 1..]),
            None => continue,
        };
        let path = path.trim_start_matches('"').trim_end_matches('"');
        let p = PathBuf::from(path);
        let st = if code.contains("??") { GitStatus::New }
            else if code.starts_with("AM") || code.contains("AM") { GitStatus::Conflicted }
            else if code.contains('M') && !code.contains("??") { GitStatus::Modified }
            else if code.contains('D') { GitStatus::Deleted }
            else { GitStatus::Other };
        if let GitStatus::Modified = st { ins += 1; }
        if let GitStatus::Deleted = st { del += 1; }
        statuses.insert(p, st);
    }
    let branch = Command::new("git").arg("-C").arg(dir).arg("rev-parse")
        .arg("--abbrev-ref").arg("HEAD").output().ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string());
    Some(GitInfo { branch, statuses, insertions: ins, deletions: del })
}

pub struct Builder<'a> {
    pub opt: TreeOptions,
    pub users: Users,
    pub budget: usize,
    pub one_level: bool,
    pub conf: &'a Conf,
    pub git: Option<GitInfo>,
}

impl<'a> Builder<'a> {
    pub fn node_meta(&self, path: &Path, name: &str) -> Node {
        let mut n = Node::new(path.to_path_buf());
        if let Some(m) = stat_path(path) {
            n.is_dir = m.is_dir; n.is_symlink = m.is_symlink; n.link_target = m.link_target;
            n.mtime = Some(m.mtime); n.perm = Some(m.mode); n.uid = m.uid; n.gid = m.gid;
            n.dev_major = Some(m.dev_major); n.dev_minor = Some(m.dev_minor);
            n.apparent = m.apparent; n.real_size = m.blocks;
            n.size = Some(size_on_disk(m.apparent, m.blocks));
            n.sparse = m.blocks < m.apparent && m.apparent > 0;
        } else { n.has_error = true; }
        n.extension = Node::extension_of(name);
        if let Some(g) = &self.git {
            if let Some(st) = g.statuses.get(path) { n.git_status = Some(*st); }
        }
        n
    }

    pub fn add_children(&self, node: &mut Node) {
        if !node.is_dir { return; }
        let entries = list_children(&node.path);
        let mut kids = Vec::new();
        for (name, is_dir) in entries {
            if name.starts_with('.') && !self.opt.show_hidden { continue; }
            let p = node.path.join(&name);
            let n = self.node_meta(&p, &name);
            if self.opt.only_folders && !n.is_dir { continue; }
            if !self.opt.show_gitignored && self.is_ignored(&p, &name) { continue; }
            kids.push(n);
        }
        node.children = kids;
        node.expanded = true;
    }

    pub fn is_ignored(&self, path: &Path, name: &str) -> bool {
        let mut dir = path.parent().map(|p| p.to_path_buf());
        while let Some(d) = dir {
            let gi = d.join(".gitignore");
            if let Ok(text) = std::fs::read_to_string(&gi) {
                for line in text.lines() {
                    let l = line.trim();
                    if l.is_empty() || l.starts_with('#') { continue; }
                    let base = l.split('/').last().unwrap_or(l).to_string();
                    if base == name { return true; }
                }
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
        false
    }

    /// grow: expand dirs (cyclic order) until the height is filled
    pub fn grow(&self, root: &mut Node, height: usize) {
        if self.one_level { return; }
        let mut guard = 0;
        loop {
            guard += 1;
            if guard > 5000 { break; }
            if root.line_count() >= height { break; }
            if !self.expand_next(root) { break; }
        }
    }

    fn expand_next(&self, node: &mut Node) -> bool {
        if !node.expanded && node.is_dir {
            self.add_children(node);
            self.deep_fill(node);
            return true;
        }
        let len = node.children.len();
        if len == 0 { return false; }
        for k in 0..len {
            let idx = (1 + k) % len;
            if node.children[idx].is_dir && !node.children[idx].expanded {
                self.add_children(&mut node.children[idx]);
                self.deep_fill(&mut node.children[idx]);
                return true;
            }
            if node.children[idx].is_dir {
                if self.expand_next(&mut node.children[idx]) { return true; }
            }
        }
        false
    }

    pub fn deep_fill(&self, node: &mut Node) {
        if !node.is_dir { return; }
        let (s, c, mt) = deep_info(&node.path, 200_000);
        node.real_size = s; node.size = Some(s); node.count = Some(c);
        if let Some(m) = mt { node.mtime = Some(node.mtime.unwrap_or(0).max(m)); }
        for c in node.children.iter_mut() {
            if c.is_dir && c.count.is_none() {
                let (s2, c2, mt2) = deep_info(&c.path, 200_000);
                c.real_size = s2; c.size = Some(s2); c.count = Some(c2);
                if let Some(m) = mt2 { c.mtime = Some(c.mtime.unwrap_or(0).max(m)); }
            }
        }
    }

    /// trim so the tree fits in `height` lines
    pub fn trim(&self, root: &mut Node, height: usize) {
        let mut guard = 0;
        loop {
            guard += 1;
            if guard > 5000 { break; }
            if root.line_count() <= height { break; }
            if !self.trim_once(root) { break; }
        }
    }

    fn trim_once(&self, node: &mut Node) -> bool {
        if let Some(i) = node.children.iter().position(|c| !c.children.is_empty()) {
            let c = &mut node.children[i];
            c.children.pop();
            c.unlisted += 1;
            if c.unlisted == 1 && !c.children.is_empty() {
                c.children.remove(0);
                c.unlisted += 1;
            }
            return true;
        }
        for c in node.children.iter_mut() {
            if self.trim_once(c) { return true; }
        }
        false
    }
}

/// flatten the tree into display lines
pub fn flatten(node: &Node, depth: usize, prefix: &str, is_root: bool, out: &mut Vec<Line>) {
    let last = true;
    let mut name = node.name.clone();
    if node.pruned { name.push_str(" …"); }
    if node.is_symlink {
        if let Some(t) = &node.link_target { name = format!("{} -> {}", node.name, t); }
    }
    out.push(Line {
        depth, path: node.path.clone(), name, is_dir: node.is_dir, is_symlink: node.is_symlink,
        is_root, is_unlisted: false, unlisted_count: 0, prefix: prefix.to_string(), last,
        has_children_shown: !node.children.is_empty(), expanded: node.expanded, pruned: node.pruned,
        size: node.size, real_size: node.real_size, apparent: node.apparent, mtime: node.mtime,
        count: node.count, perm: node.perm, uid: node.uid, gid: node.gid, sparse: node.sparse,
        git_status: node.git_status, extension: node.extension.clone(), has_error: node.has_error,
        link_target: node.link_target.clone(), dev_major: node.dev_major, dev_minor: node.dev_minor,
    });
    let n = node.children.len();
    for (i, c) in node.children.iter().enumerate() {
        let lastc = i + 1 == n;
        let mut p2 = String::from(prefix);
        p2.push_str(if last { "   " } else { "│  " });
        p2.push_str(if lastc { "└──" } else { "├──" });
        flatten(c, depth + 1, &p2, false, out);
    }
    if node.unlisted > 0 {
        let mut p2 = String::from(prefix);
        p2.push_str(if last { "   " } else { "│  " });
        p2.push_str("└──");
        out.push(Line {
            depth: depth + 1, path: node.path.clone(),
            name: format!("{} unlisted", node.unlisted),
            is_dir: false, is_symlink: false, is_root: false, is_unlisted: true,
            unlisted_count: node.unlisted, prefix: p2, last: true, has_children_shown: false,
            expanded: false, pruned: false, size: None, real_size: 0, apparent: 0, mtime: None,
            count: None, perm: None, uid: 0, gid: 0, sparse: false, git_status: None,
            extension: String::new(), has_error: false, link_target: None,
            dev_major: None, dev_minor: None,
        });
    }
}

pub fn build(root: &Path, opt: &TreeOptions, height: usize, conf: &Conf, one_level: bool, gi: Option<GitInfo>) -> Tree {
    let b = Builder { opt: opt.clone(), users: Users::new(), budget: height, one_level, conf, git: gi };
    let mut node = b.node_meta(root, "");
    node.is_dir = true;
    if one_level {
        b.add_children(&mut node);
    } else {
        b.grow(&mut node, height);
        b.trim(&mut node, height);
    }
    if let Some(g) = &b.git {
        for c in node.children.iter_mut() {
            if let Some(st) = g.statuses.get(&c.path) { c.git_status = Some(*st); }
        }
    }
    let mut lines = Vec::new();
    flatten(&node, 0, "", true, &mut lines);
    let git = b.git.as_ref();
    Tree {
        root: root.to_path_buf(),
        lines,
        selected: 0,
        top: 0,
        total: 0,
        git_branch: git.and_then(|g| g.branch.clone()),
        git_insertions: git.map(|g| g.insertions).unwrap_or(0),
        git_deletions: git.map(|g| g.deletions).unwrap_or(0),
        force_one_level: one_level,
    }
}
RSEOF
echo ok"}

