fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else if cur.chars().count() + 1 + word.chars().count() <= width {
            cur.push(' '); cur.push_str(word);
        } else {
            cur.push(' ');
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        }
    }
    lines.push(cur);
    lines
}

fn centered(s: &str, width: usize) -> String {
    let l = s.chars().count();
    if l >= width { return s.to_string(); }
    let pad = (width - l) / 2;
    " ".repeat(pad) + s
}

/// print the CLI help
pub fn print_help(_c: &Cli) {
