fn help_col_widths(avail: usize) -> Vec<usize> {
    let nat = [8usize, 30, 68];
    let total: usize = nat.iter().sum();
    if total <= avail { return nat.to_vec(); }
    let mut w = nat;
    let mut over = total - avail;
    for (i, idx) in [2usize, 1, 0, 2, 1, 0].iter().enumerate() {
        let floor = if i < 3 { [4usize, 15, 38][*idx] } else { [3usize, 3, 3][*idx] };
        if w[*idx] > floor {
            let take = (w[*idx] - floor).min(over);
            w[*idx] -= take; over -= take;
            if over == 0 { break; }
        }
    }
    w
}

fn pad_center(s: &str, w: usize) -> String {
    let l = s.chars().count();
    if l >= w { return s.chars().take(w).collect(); }
    let p = (w - l) / 2;
    " ".repeat(p) + s + &" ".repeat(w - l - p)
}
fn pad_left(s: &str, w: usize) -> String {
    let l = s.chars().count();
    if l >= w { return s.chars().take(w).collect(); }
    s.to_string() + &" ".repeat(w - l)
}

