/// parse the verbs from the default verbs.hjson resource
pub fn parse_verb_conf() -> Vec<VerbConf> {
    let v = crate::hjson::parse(crate::conf::DEFAULT_VERBS_HJSON).unwrap_or(crate::hjson::Value::Null);
    let mut out = Vec::new();
    if let Some(a) = v.get("verbs").and_then(|x| x.as_arr()) {
        for item in a {
            let invocation = item.get("invocation").and_then(|x| x.as_str()).or_else(|| item.get("name").and_then(|x| x.as_str())).unwrap_or("");
            let name = invocation.split_whitespace().next().unwrap_or("").to_string();
            let args = invocation.split_whitespace().skip(1).count();
            out.push(VerbConf {
                name, invocation: invocation.to_string(),
                shortcut: item.get("shortcut").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                key: item.get("key").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                execution: item.get("execution").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                internal: item.get("internal").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                external: item.get("external").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                leave_broot: item.get("leave_broot").and_then(|x| x.as_bool()).unwrap_or(false),
                auto_exec: item.get("auto_exec").and_then(|x| x.as_bool()).unwrap_or(true),
                from_shell: item.get("from_shell").and_then(|x| x.as_bool()).unwrap_or(false),
                set_working_dir: item.get("set_working_dir").and_then(|x| x.as_bool()).unwrap_or(false),
                apply_to: item.get("apply_to").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                extension: item.get("extension").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                description: item.get("description").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                args_needed: args > 0,
                is_internal: false,
            });
        }
    }
    out
}
