pub fn search_table(_w: usize) -> Vec<String> {
    let rows = [
        ("    f/", "fuzzy search on file name", "f/conh matches DefaultConf.hjson"),
        ("     /", "regex search on file name", "/rs$ matches build.rs"),
        ("    e/", "exact string search on file name", "e/feat matches help_features.rs"),
        ("   nt/", "tokens search on file name", "nt/fea,he matches HelpFeature.java"),
        ("   ep/", "exact string search on sub path", "ep/te\\/do matches website/docs"),
        ("      ", "fuzzy search on sub path", "flam matches src/flag/mod.rs"),
        ("   rp/", "regex search on sub path", "rp/\\d{3}.*txt matches dir/a123/b.txt"),
        ("    t/", "tokens search on sub path", "t/help,doc matches website/docs/help.md"),
        ("    c/", "exact string search on file content", "c/find( matches a file containing a.find(b);"),
        ("   cr/", "regex search on file content", "cr/find/i matches a file containing A::Find(b)"),
    ];
    let c1 = 6; let c2 = 35; let c3 = 46;
    let mut v = Vec::new();
    v.push(format!("┌{}┬{}┬{}┐", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3)));
    v.push(format!("│{}│{}│{}│", pad_center("prefix", c1), pad_center("search", c2), pad_left("example", c3)));
    v.push(format!("├{}┼{}┼{}┤", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3)));
    for r in rows {
        v.push(format!("│{}│{}│{}│", pad_center(r.0, c1), pad_left(r.1, c2), pad_left(r.2, c3)));
    }
    v.push(format!("└{}┴{}┴{}┘", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3)));
    v
}

pub fn verb_table(_w: usize, filter: &str) -> Vec<String> {
    let verbs = crate::verbs::all_verbs(&crate::conf::parse_verb_conf());
    let f = filter.trim_start_matches(':').trim_start_matches(' ').to_lowercase();
    let rows: Vec<&crate::verbs::Verb> = verbs.iter().filter(|v| f.is_empty()
        || v.name.to_lowercase().contains(&f) || v.shortcut.to_lowercase().contains(&f)
        || v.key.to_lowercase().contains(&f) || v.description.to_lowercase().contains(&f)
        || v.execution.to_lowercase().contains(&f)).collect();
    let c1 = 26; let c2 = 8; let c3 = 22; let c4 = 58;
    let mut v = Vec::new();
    v.push(format!("┌{}┬{}┬{}┬{}┐", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3), "─".repeat(c4)));
    v.push(format!("│{}│{}│{}│{}│", pad_center("name", c1), pad_center("shortcut", c2), pad_center("key", c3), pad_left("description", c4)));
    v.push(format!("├{}┼{}┼{}┼{}┤", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3), "─".repeat(c4)));
    for r in rows {
        let desc = if r.execution.is_empty() && r.internal.is_empty() && r.external.is_empty() { String::new() }
            else if !r.execution.is_empty() { r.execution.clone() }
            else if !r.external.is_empty() { r.external.clone() }
            else { format!(":{}", r.internal) };
        for (i, dl) in wrap(&desc, c4).into_iter().enumerate() {
            let a = if i == 0 { pad_left(&r.name, c1) } else { " ".repeat(c1) };
            let b = if i == 0 { pad_center(&r.shortcut, c2) } else { " ".repeat(c2) };
            let c = if i == 0 { pad_center(&r.key, c3) } else { " ".repeat(c3) };
            v.push(format!("│{}│{}│{}│{}│", a, b, c, pad_left(&dl, c4)));
        }
    }
    v.push(format!("└{}┴{}┴{}┴{}┘", "─".repeat(c1), "─".repeat(c2), "─".repeat(c3), "─".repeat(c4)));
    v
}
