use crate::args::Cli;
use crate::conf::Conf;
use crate::tree::{self, Tree, TreeOptions, SortMode, GitStatus};
use std::path::PathBuf;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Action { None, Quit, Refresh }

pub struct State {
    pub root: PathBuf,
    pub conf: Conf,
    pub opt: TreeOptions,
    pub tree: Tree,
    pub input: String,
    pub show_root_fs: bool,
    pub sizes: bool,
    pub dates: bool,
    pub perms: bool,
    pub counts: bool,
    pub bar: bool,
    pub git_info: bool,
    pub show_selection_mark: bool,
    pub width: usize,
    pub height: usize,
}

impl State {
    pub fn rebuild(&mut self) {
        let height = self.height.saturating_sub(2);
        let one_level = matches!(self.opt.sort, SortMode::Count | SortMode::Date | SortMode::Size | SortMode::TypeDirsFirst | SortMode::TypeDirsLast) || self.opt.no_tree;
        let gi = if self.git_info { tree::git_info(&self.root) } else { None };
        self.tree = tree::build(&self.root, &self.opt, height, &self.conf, one_level, gi);
    }
}

/// run the interactive application
pub fn run(args: Cli) {
    let sty = match args.color.as_deref() { Some("no") => false, _ => true };
    let _ = sty;
    // make sure the conf exists
    let cdir = Conf::default();
    let _ = cdir;
    let d = crate::conf::config_dir();
    let mut created = false;
    if !d.join("conf.hjson").exists() {
        let _ = crate::conf::write_default_files(&d);
        created = true;
    }
    if crate::std::env::var("BR_INSTALL").map(|v| v != "no").unwrap_or(true) {
        crate::install::maybe_install(&args);
    }
    if created { crate::conf::print_new_conf_message(&d, true); }
    let mut conf = crate::conf::load_conf(&None, crate::conf::Luma::Dark);
    // apply the launch flags
    let mut opt = TreeOptions::default();
    let mut sizes = false; let mut dates = false; let mut perms = false; let mut counts = false;
    let mut bar = false; let mut git_info = false; let mut show_root_fs = false;
    if let Some(f) = parse_flags(&conf.default_flags) { apply_flags(&mut opt, &mut sizes, &mut dates, &mut perms, &mut counts, &mut bar, &mut git_info, &mut show_root_fs, &f); }
    if let Some(f) = parse_flags(&args_str(&args)) { apply_flags(&mut opt, &mut sizes, &mut dates, &mut perms, &mut counts, &mut bar, &mut git_info, &mut show_root_fs, &f); }
    let root = args.root.clone().unwrap_or_else(|| PathBuf::from("."));
    let root = std::fs::canonicalize(&root).unwrap_or(root);
    let (w, h) = crate::crossterm::terminal::size().unwrap_or((80, 24));
    let mut st = State {
        root, conf, opt, tree: Tree { root: PathBuf::new(), lines: vec![], selected: 0, top: 0, total: 0, git_branch: None, git_insertions: 0, git_deletions: 0, force_one_level: false },
        input: String::new(), show_root_fs, sizes, dates, perms, counts, bar, git_info,
        show_selection_mark: true, width: w as usize, height: h as usize,
    };
    st.conf.counts_on = counts;
    st.conf.dates_on = dates;
    st.conf.perms_on = perms;
    st.conf.bar_on = bar || matches!(st.opt.sort, SortMode::Size | SortMode::Count);
    st.rebuild();
    // the commands from -c
    let cmds = args.cmd.clone().unwrap_or_default();
    if !cmds.is_empty() {
        let sep = std::env::var("BROOT_CMD_SEPARATOR").unwrap_or_else(|_| ";".to_string());
        let _ = crate::app::exec_cmds(&mut st, &cmds, &sep, &args);
        return;
    }
    crate::app::tui(&mut st, &args);
}

pub fn args_str(a: &Cli) -> String {
    let mut s = String::new();
    if a.sizes.unwrap_or(false) { s.push('s'); }
    if a.dates.unwrap_or(false) { s.push('d'); }
    if a.permissions.unwrap_or(false) { s.push('p'); }
    if a.hidden.unwrap_or(false) { s.push('h'); }
    if a.gitignored.unwrap_or(false) { s.push('i'); }
    if a.only_folders.unwrap_or(false) { s.push('f'); }
    if a.show_git_info.unwrap_or(false) { s.push('g'); }
    if a.show_root_fs.unwrap_or(false) { s.push('\x01'); }
    if a.whale_spotting.unwrap_or(false) { s.push('w'); }
    if a.trim_root.unwrap_or(false) { s.push('t'); }
    s
}

pub fn parse_flags(s: &str) -> Option<String> {
    let mut out = String::new();
    let mut in_flag = false;
    for ch in s.chars() {
        if ch == '-' { in_flag = true; continue; }
        if ch.is_whitespace() { in_flag = false; continue; }
        if in_flag { out.push(ch); }
    }
    if out.is_empty() { None } else { Some(out) }
}

pub fn apply_flags(opt: &mut TreeOptions, sizes: &mut bool, dates: &mut bool, perms: &mut bool, counts: &mut bool, bar: &mut bool, git: &mut bool, rfs: &mut bool, f: &str) {
    for ch in f.chars() {
        match ch {
            's' => *sizes = true, 'S' => *sizes = false,
            'd' => *dates = true, 'D' => *dates = false,
            'p' => *perms = true, 'P' => *perms = false,
            'h' => opt.show_hidden = true, 'H' => opt.show_hidden = false,
            'i' => opt.show_gitignored = true, 'I' => opt.show_gitignored = false,
            'f' => opt.only_folders = true, 'F' => opt.only_folders = false,
            'g' => *git = true, 'G' => *git = false,
            'w' => { opt.sort = SortMode::Size; opt.show_hidden = true; opt.show_gitignored = true; *bar = true; }
            'W' => { opt.sort = SortMode::None; opt.show_hidden = false; opt.show_gitignored = false; *bar = false; }
            't' => {}, 'T' => {},
            'c' => *counts = true,
            'e' => *bar = true,
            '\x01' => *rfs = true,
            _ => {}
        }
    }
}

/// execute a semicolon separated command list
pub fn exec_cmds(st: &mut State, cmds: &str, sep: &str, args: &Cli) -> Result<(), String> {
    let _ = sep;
    for c in crate::app::split_cmds(cmds, sep) {
        let act = crate::verbs_cmd::exec(st, &c, args);
        if act == Action::Quit { break; }
    }
    Ok(())
}

pub fn split_cmds(s: &str, sep: &str) -> Vec<String> {
    if sep == ";" { s.split(';').map(|x| x.to_string()).collect() } else { s.split(sep.as_str()).map(|x| x.to_string()).collect() }
}

/// the main interactive loop
pub fn tui(st: &mut State, args: &Cli) {
    use crate::crossterm::{event, terminal, execute};
    use std::io::Write;
    let mut stdout = std::io::stdout();
    let _ = execute!(stdout, terminal::EnterAlternateScreen, terminal::Hide, event::EnableMouseCapture);
    let _ = terminal::enable_raw_mode();
    loop {
        crate::render::draw(st);
        let _ = stdout.flush();
        if let event::Event::Key(k) = event::read().unwrap_or_else(|_| event::Event::FocusGained) {
            if !k.kind.is_press() { continue; }
            use crate::crossterm::event::KeyCode as K;
            match k.code {
                K::Char('q') if k.modifiers.contains(crate::crossterm::event::KeyModifiers::CONTROL) => break,
                K::Char('c') if k.modifiers.contains(crate::crossterm::event::KeyModifiers::CONTROL) => break,
                K::Esc => { if st.input.is_empty() { break; } else { st.input.clear(); } }
                K::Char('?') => { crate::render::show_help(st); }
                K::Char(c) => st.input.push(c),
                K::Down => { crate::app::line_down(st); }
                K::Up => { crate::app::line_up(st); }
                K::Backspace => { st.input.pop(); }
                _ => {}
            }
        }
    }
    let _ = execute!(std::io::stdout(), terminal::LeaveAlternateScreen, terminal::Show, event::DisableMouseCapture);
    let _ = terminal::disable_raw_mode();
}

pub fn line_down(st: &mut State) {
    if st.tree.selected + 1 < st.tree.lines.len() { st.tree.selected += 1; }
}
pub fn line_up(st: &mut State) {
    if st.tree.selected > 0 { st.tree.selected -= 1; }
}
