use crate::app::{Action, State};

pub fn draw(st: &mut State) {
    use std::io::Write;
    let mut out = std::io::stdout();
    let _ = write!(out, "\x1b[?25l\x1b[H");
    let h = st.height;
    let w = st.width;
    let tree_rows = h.saturating_sub(2);
    let lines = &st.tree.lines;
    for i in 0..tree_rows {
        let _ = write!(out, "\x1b[2K");
        if let Some(l) = lines.get(st.tree.top + i) {
            let sel = st.tree.selected == st.tree.top + i;
            let s = crate::render_line::render(l, st, sel, w);
            let _ = write!(out, "{}", s);
        }
        let _ = write!(out, "\x1b[0m\r\n");
    }
    let _ = write!(out, "\x1b[2K\x1b[0m\r\n");
    let _ = write!(out, "\x1b[2K\x1b[0m");
    let _ = out.flush();
}

