use crate::app::State;
use crate::tree::{Line, format_size, format_date, GitStatus};
use crate::skin::Sk;

pub fn render(l: &Line, st: &State, selected: bool, width: usize) -> String {
    let sk = crate::skin::new_sk();
    let _ = &sk;
    let mut out = String::new();
    // mark / git
    if !l.is_root {
        if selected && st.show_selection_mark { out.push_str("\x1b[1m\x1b[38;5;110m"); out.push('\u{25b6}'); out.push_str("\x1b[0m\x1b[39m"); }
        else {
            match l.git_status {
                Some(GitStatus::Modified) => { out.push_str("\x1b[38;5;28mM\x1b[39m"); }
                Some(GitStatus::New) => { out.push_str("\x1b[1m\x1b[38;5;94mN\x1b[0m"); }
                Some(GitStatus::Conflicted) => { out.push_str("\x1b[38;5;88m?\x1b[39m"); }
                _ => { out.push(' '); }
            }
        }
    }
    if let Some(sel_style) = if selected { Some("\x1b[48;5;238m") } else { None } { let _ = sel_style; }
    // size
    if let Some(sz) = l.size {
        let s = format_size(sz);
        let w = if l.is_root { st.conf.size_w } else { st.conf.size_w + 1 };
        let pad = w.saturating_sub(s.len());
        if l.is_dir { out.push_str("\x1b[1m"); out.push_str("\x1b[38;5;110m"); } else { out.push_str("\x1b[38;5;254m"); }
        if selected { out.push_str("\x1b[48;5;238m"); }
        for _ in 0..pad { out.push(' '); }
        out.push_str(&s);
        out.push(' ');
        if l.sparse { out.push_str("\x1b[38;5;214m"); out.push('s'); out.push_str("\x1b[39m"); } else { out.push(' '); }
        if l.is_dir { out.push_str("\x1b[0m"); } else { out.push_str("\x1b[39m"); }
    } else if !l.is_root {
        let w = st.conf.size_w + 1;
        for _ in 0..w { out.push(' '); }
    }
    // date
    if st.dates {
        if let Some(m) = l.mtime {
            out.push_str("\x1b[38;5;66m"); out.push_str(&format_date(m, "%Y/%m/%d %R")); out.push_str("\x1b[39m ");
        } else { for _ in 0..17 { out.push(' '); } }
    }
    // permissions
    if st.perms {
        if let Some(m) = l.perm {
            let p = crate::display::perm_string(m);
            for ch in p.chars() {
                let (c, b) = match ch { 'r' => (94, "r"), 'w' => (132, "w"), 'x' => (65, "x"), _ => (237, "_") };
                let _ = b;
                out.push_str(&format!("\x1b[38;5;{}m{}", c, ch));
            }
            out.push_str(&format!("\x1b[38;5;138m {}", crate::app::user_name(l.uid)));
            out.push_str(&format!("\x1b[38;5;131m {}", crate::app::group_name(l.gid)));
            out.push_str("\x1b[39m ");
        } else { for _ in 0..21 { out.push(' '); } }
    }
    // count
    if st.counts {
        if let Some(c) = l.count {
            let s = c.to_string();
            let pad = st.conf.count_w.saturating_sub(s.len());
            for _ in 0..pad { out.push(' '); }
            out.push_str("\x1b[38;5;138m"); out.push_str(&s); out.push_str("\x1b[39m");
            out.push(' ');
        } else { for _ in 0..st.conf.count_w + 1 { out.push(' '); } }
    }
    // branch
    if !l.is_root {
        out.push_str("\x1b[38;5;240m"); out.push_str(&l.prefix); out.push_str("\x1b[39m");
    }
    // name
    if l.is_unlisted { out.push_str("\x1b[38;5;244m\x1b[3m"); } else if l.is_dir { out.push_str("\x1b[1m\x1b[38;5;110m"); } else { out.push_str("\x1b[38;5;254m"); }
    if selected { out.push_str("\x1b[48;5;238m"); }
    out.push_str(&l.name);
    out.push_str("\x1b[0m\x1b[39m");
    if selected { out.push_str("\x1b[38;5;254m\x1b[48;5;238m"); }
    let _ = width;
    out
}
